-- Quests (validated by quest_v2_check; edit them later in the Game console › Quests).
select eldervale_private.quest_arc_put('a3c0b000-0001-4000-8000-000000000003',$q${"chain":"arc-crown","order":3,"published":true,"objectives":[],"key":"arc-crown-3","name":"Grain for the Frost Gate","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0001-4000-8000-000000000004","icon":"wheat","requirements":{"quests":["arc-crown-2","arc-frontier-2"],"skills":{"agility":{"level":20,"boostable":false}},"combat":25},"description":"The forged writs emptied the royal granary at the Farm Gate while Winterwatch went hungry. Captain Varn wants to know where the grain really went, and who loaded it.","dialogue":{"offer":[{"who":"npc","text":"Winterwatch starved this winter. You may have heard. You may have fed some of them."},{"who":"npc","text":"The writs said the grain went north through the Frost Gate. The Frost Gate wardens never saw it."},{"who":"npc","text":"So it left by the Farm Gate, at night, past my own granary. Talk to Hobb Wainright, the drover. Gently. He frightens easily and kicks harder."}],"progress":[{"who":"npc","text":"The granary will not count itself. Unfortunately."}],"complete":[{"who":"npc","text":"My hand? My hand on the loading orders?"},{"who":"npc","text":"...It is a good copy. A very good copy. Thank you for bringing it to me and not to the court."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"told_odo":true},"lines":[{"who":"npc","text":"Odo came to me first, trembling like a leaf in a gale, and told me someone was copying my hand. You trusted the right clerk."},{"who":"npc","text":"Whoever M.A. is, they want me blamed. Thank you for not obliging them."}]}],"stages":[{"id":"drover","journal":"Captain Varn believes the stolen grain left Birchford by the Farm Gate at night. Hobb Wainright, the drover outside the Farm Gate, might have seen the carts.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-00000000000a","amount":1,"label":"Ask Hobb Wainright the drover about night carts","dialogue":[{"who":"npc","text":"Night carts? Every third night, Watch orders, very proper. Varrow-looking lads driving."},{"who":"npc","text":"They load at the old tithe yard west of the farm. Go after dark, keep low, and mind the dogs. There are no dogs. That is what worries me."}]}]},{"id":"yard","journal":"Hobb said the night carts load at the old tithe yard west of the farm, under proper-looking Watch orders. I should creep up on the yard and see what is being loaded.","objectives":[{"type":"visit","x":-292,"z":138,"radius":4,"amount":1,"label":"Sneak up to the tithe yard west of the farm"}]},{"id":"ambush","journal":"The tithe yard was full of sacks stamped for Winterwatch, and full of men wearing old Varrow crowns stitched inside their collars. They saw me.","onEnter":{"cutscene":"ambush"},"objectives":[{"type":"event","event":"death","targets":["a3c0a000-0001-4000-9000-000000000002","a3c0a000-0001-4000-9000-000000000003","a3c0a000-0001-4000-9000-000000000004"],"amount":3,"label":"Fight off the Varrow cutthroats"}]},{"id":"orders","journal":"I beat off the cutthroats. In the foreman’s strongbox I found the loading orders — signed, it seems, in Captain Varn’s own hand. Before I decide whom to tell, Hobb wants the honest weight back: five sacks of wheat for Winterwatch.","npc":"a3c0a000-0001-4000-8000-00000000000a","objectives":[{"type":"collect","target":"wheat","amount":5,"label":"Bring Hobb five bundles of wheat for the Winterwatch cart"}],"dialogue":{"choice":[{"who":"npc","text":"Five bundles. The first honest grain to go north all year."},{"who":"npc","text":"That paper in your hand. Is that the Captain’s writing? Then who do you tell, friend? I would not want to be you."}]},"choices":[{"id":"confront","label":"I’ll show Captain Varn the orders to her face.","flags":{"confronted_varn":true},"dialogue":[{"who":"npc","text":"Brave. Or daft. Same thing, mostly, at the Keep."}]},{"id":"odo","label":"I’ll take them to Odo first. Quietly.","flags":{"told_odo":true},"dialogue":[{"who":"npc","text":"The little clerk? Hah. He is smarter than he looks. He would have to be."}]}]},{"id":"handover","journal":"The orders bear Captain Varn’s handwriting. I have decided how to handle it; now I must hand the loading orders to the Captain and watch her face.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000004","amount":1,"label":"Show Captain Varn the loading orders","dialogue":[{"who":"npc","text":"These are mine. Or they look mine. Look at the “V”, though. I have never closed a “V” in my life."}]}]}],"cutscenes":{"ambush":{"name":"The tithe yard","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-00000000000a","distance":5,"height":2.2,"angle":30}},{"title":"Varrow’s men","subtitle":"West of the Farm Gate","ms":2400},{"say":{"who":"npc","name":"Hobb Wainright","text":"Told you there were no dogs. There are worse than dogs."},"shot":{"around":"a3c0a000-0001-4000-8000-00000000000a","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"framed":{"name":"A good copy","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"Someone wants a culprit","subtitle":"Crown Court, Birchford","ms":2400},{"say":{"who":"npc","name":"Captain Isolde Varn","text":"Someone has been practising my signature. In the same ink Old Sable’s pupil uses. I think I am meant to hang for this."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"framed"},"journalDone":"The royal grain left by the Farm Gate on forged Watch orders and was loaded by Varrow cutthroats. The orders are in a copy of Captain Varn’s hand: someone wants her blamed. Five honest bundles of wheat went north to Winterwatch.","journalVariants":[{"ifFlags":{"confronted_varn":true},"text":"I showed the Captain the orders to her face."},{"ifFlags":{"told_odo":true},"text":"I went to Odo first, quietly, and he warned the Captain."}],"gold":600,"xp":{"agility":7000,"strength":5000,"farming":3000},"lamps":[{"perLevel":10,"minLevel":15,"label":"Drover’s lamp"}],"unlocks":[{"type":"flag","id":"crown.granary_saved","label":"Birchford’s granary sends grain north again"},{"type":"dialogue","id":"dialogue.crown-hobb-3","label":"Hobb drives honest carts","npc":"a3c0a000-0001-4000-8000-00000000000a","lines":[{"who":"npc","text":"Twelve carts went north this week. Real ones. With dogs."}]},{"type":"dialogue","id":"dialogue.crown-odo-3","label":"Odo is now brave (slightly)","npc":"a3c0a000-0001-4000-8000-000000000001","ifFlags":{"told_odo":true},"lines":[{"who":"npc","text":"I walked into the Captain’s office without knocking. I have never felt so alive. I had to sit down afterwards."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0001-4000-8000-000000000004',$q${"chain":"arc-crown","order":4,"published":true,"objectives":[],"key":"arc-crown-4","name":"The Mistress of Ceremonies","questPoints":3,"difficulty":"Experienced","length":"Long","giver":"a3c0a000-0001-4000-8000-000000000001","icon":"candle","requirements":{"quests":["arc-crown-3"],"qp":16,"skills":{"crafting":{"level":30,"boostable":false},"smithing":{"level":20,"boostable":false},"agility":{"level":25,"boostable":false}}},"description":"Captain Varn has been arrested on the word of Lady Merrow Ashgrove, the Queen’s Mistress of Ceremonies. Odo is beside himself, and the Feast of Lamps is in three days.","dialogue":{"offer":[{"who":"npc","text":"They took her. The Captain. In chains, in the middle of Crown Court, on the say-so of Lady Merrow Ashgrove!"},{"who":"npc","text":"Lady Merrow plans the Feast of Lamps. Lady Merrow plans everything. M.A., you said? Merrow Ashgrove. I feel faint."},{"who":"player","text":"We need proof the Queen will believe."},{"who":"npc","text":"Then we need the forger herself. Ivy Sable. Find her, please, before Lady Merrow does."}],"progress":[{"who":"npc","text":"The Feast is coming and the Captain is in a cell. I have sealed my door twice."}],"complete":[{"who":"npc","text":"The Captain is free! On the strength of a writ sealed with an honest seal cast by Marta herself. Beautiful. Legal. Nearly."},{"who":"npc","text":"And Lady Merrow has gone very quiet, and very quietly asked for the keys to the old Undervault. Here, take these. If she goes down there, so do we."}]},"stages":[{"id":"ivy","journal":"Lady Merrow Ashgrove — M.A. — had Captain Varn arrested. Odo begged me to find Ivy Sable, the forger, before Merrow does. Ivy writes letters for people near the Gilded Antler on Southgate Row.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000007","amount":1,"label":"Find Ivy Sable on Southgate Row","dialogue":[{"who":"npc","text":"You are the one who found Grandfather’s mark."},{"who":"npc","text":"She found me when I was fifteen. Paid our debts, gave me a room, gave me orders. Lady Merrow does not hire people. She owns them."},{"who":"npc","text":"She is a Varrow, on her mother’s side. She does not want the throne. She wants a Varrow king on it, and she has made one."},{"who":"player","text":"Made one?"},{"who":"npc","text":"Out of wax. Out of my moulds and the Varrow crown she kept. She will light it at the Feast of Lamps. The ceremony is written in her cipher. I can read it, if you can find the lamps."}]}]},{"id":"first-lamp","journal":"Ivy says Merrow is a Varrow and means to crown a king made of wax at the Feast of Lamps. Merrow’s ceremony is hidden in a lamp-lighter’s cipher: “Where the bell was quiet, first.” That sounds like the top of Bell Lane.","onEnter":{"cutscene":"cipher"},"objectives":[{"type":"visit","x":-226.8,"z":95,"radius":3,"amount":1,"label":"Find the first lamp of the cipher"}]},{"id":"second-lamp","journal":"At the top of Bell Lane a lamp-post had a candle-flame scratched into it, and a second line: “Then where the prayers walk west.” The little lane west of the temple of the Morning Bell runs that way.","objectives":[{"type":"visit","x":-250,"z":118,"radius":3,"amount":1,"label":"Find the second lamp of the cipher"}]},{"id":"third-lamp","journal":"The end of Chapel Lane held the second mark: “Last where the market meets the dawn.” Market Street runs east towards the Ember Gate and the sunrise.","objectives":[{"type":"visit","x":-176,"z":133.5,"radius":3,"amount":1,"label":"Find the third lamp of the cipher"}]},{"id":"chancellor","journal":"With the three marks, Ivy read the cipher: the ceremony’s instructions are kept in the old Chancellor’s House by Crown Court, which Merrow uses as her dressing rooms. I need to slip in without being seen.","objectives":[{"type":"visit","x":-246.5,"z":190.5,"radius":3,"amount":1,"label":"Slip into the Chancellor’s House by Crown Court"}]},{"id":"true-seal","journal":"Merrow’s instructions name the Undervault below the Keep, where the wax king waits. To free Captain Varn in time, Odo needs a release writ sealed with a true seal. Marta Kell can cast one if I bring her a silver bar.","npc":"a3c0a000-0001-4000-8000-000000000002","objectives":[{"type":"collect","target":"silverBar","amount":1,"label":"Bring Marta Kell a silver bar for a true seal"}],"dialogue":{"advance":[{"who":"npc","text":"Silver for a royal seal. Pressed, not cast, as the old rules say. Watch."},{"who":"npc","text":"There. Now Odo can write the release and nobody in Birchford can say it is false."}]}},{"id":"release","journal":"Marta pressed a true royal seal. I should take it to Captain Varn in the Keep cells by Crown Court so the release can be made in her presence, then report to Odo.","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000004","amount":1,"label":"Free Captain Varn","dialogue":[{"who":"npc","text":"A true seal, Marta’s pressing. Odo’s handwriting. And you."},{"who":"npc","text":"The Feast of Lamps. Merrow means to light her king in the Undervault. Get the keys from Odo. I will gather the Watch."}]}]}],"cutscenes":{"cipher":{"name":"The lamp-lighter’s cipher","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000007","distance":5,"height":2.2,"angle":30}},{"title":"Merrow’s cipher","subtitle":"Southgate Row, Birchford","ms":2400},{"say":{"who":"npc","name":"Ivy Sable","text":"Three lamps, three lines. Lamplighters used to mark the old routes this way. Merrow loves anything old."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000007","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"keys":{"name":"The Undervault keys","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"Below the Keep","subtitle":"Crown Court, Birchford","ms":2400},{"say":{"who":"npc","name":"Lady Merrow Ashgrove","text":"How kind of you all to fuss. The Feast will be unforgettable. I have seen to that."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"keys"},"journalDone":"Ivy Sable revealed that Lady Merrow Ashgrove is a Varrow who has made a king of wax to crown at the Feast of Lamps. I followed her lamp cipher, read her instructions in the Chancellor’s House, and freed Captain Varn with a true seal. Odo gave me the keys to the Undervault.","gold":1200,"xp":{"crafting":20000,"agility":15000,"smithing":12000},"lamps":[{"amount":15000,"minLevel":30,"label":"Lamplighter’s lamp (any skill of level 30+)"}],"unlocks":[{"type":"area","id":"area.crown-undervault","label":"The Undervault hatch at Crown Court"},{"type":"flag","id":"crown.varn_freed","label":"Captain Varn is free"},{"type":"dialogue","id":"dialogue.crown-marta-4","label":"Marta presses true seals","npc":"a3c0a000-0001-4000-8000-000000000002","lines":[{"who":"npc","text":"I press every royal seal by hand now. My wrists ache. My conscience does not."}]},{"type":"dialogue","id":"dialogue.crown-ivy-4","label":"Ivy is free of Merrow","npc":"a3c0a000-0001-4000-8000-000000000007","lines":[{"who":"npc","text":"I write letters for people who cannot. Honest ones. They pay in turnips. I have never been happier."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0001-4000-8000-000000000005',$q${"chain":"arc-crown","order":5,"published":true,"objectives":[],"key":"arc-crown-5","name":"The Tallow Crown","questPoints":5,"difficulty":"Master","length":"Very long","giver":"a3c0a000-0001-4000-8000-000000000004","icon":"custom_qa_tallow_signet","requirements":{"quests":["arc-crown-1","arc-crown-2","arc-crown-3","arc-crown-4"],"qp":36,"skills":{"crafting":{"level":45,"boostable":false},"agility":{"level":40,"boostable":false},"smithing":{"level":40,"boostable":false}},"combat":55},"description":"The Feast of Lamps has come. Lady Merrow Ashgrove means to crown a king of wax in the Undervault below Birchford Keep. Captain Varn means to stop her. So do you.","dialogue":{"offer":[{"who":"npc","text":"The Feast starts at dusk. Merrow will play the gracious host up here while her wax king waits below."},{"who":"npc","text":"We light the Feast honestly, we unmask her in front of the whole court, and when she runs, we follow her down."},{"who":"player","text":"Then let’s light some lamps."},{"who":"npc","text":"Odo wants candles. Of course he does. Go on."}],"progress":[{"who":"npc","text":"The Watch holds the court. The Undervault is yours."}],"complete":[{"who":"npc","text":"The Varrow crown, melted. And the wax king is a puddle on a chapel floor."},{"who":"npc","text":"Her Majesty asked me to give you this signet, and her thanks, and the freedom of the Treasury stair. You have earned more. These are what we have."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"exiled_merrow":true},"lines":[{"who":"npc","text":"Exile. You showed her mercy she never showed anyone. Her Majesty approves, which surprised me."},{"who":"npc","text":"Take this signet, her thanks, and the freedom of the Treasury stair."}]},{"stage":"complete","ifFlags":{"tried_merrow":true},"lines":[{"who":"npc","text":"Merrow will stand trial before the whole court, as the law wants. It will be ugly. It will be fair."},{"who":"npc","text":"Take this signet, Her Majesty’s thanks, and the freedom of the Treasury stair."}]}],"stages":[{"id":"candles","journal":"Tonight is the Feast of Lamps. Captain Varn will unmask Lady Merrow before the court. First, Odo wants the Feast lit honestly: four candles from someone he trusts.","npc":"a3c0a000-0001-4000-8000-000000000001","onEnter":{"cutscene":"feast"},"objectives":[{"type":"collect","target":"candle","amount":4,"label":"Bring Odo four candles for the Feast of Lamps"}],"dialogue":{"advance":[{"who":"npc","text":"Four honest flames. If she wanted ceremony, she shall have it, and all of it true."}]}},{"id":"unmask","journal":"The Feast candles are lit. Captain Varn is waiting at Crown Court for the moment to read Merrow’s cipher aloud before the court.","objectives":[{"type":"visit","x":-232,"z":170,"radius":5,"amount":1,"label":"Stand with Captain Varn at the Feast in Crown Court"}]},{"id":"descend","journal":"Captain Varn read Merrow’s cipher before the whole court. Merrow laughed, threw her goblet into a brazier, and fled through the Undervault hatch. I must follow her into the Undervault.","onEnter":{"cutscene":"unmasked"},"objectives":[{"type":"visit","x":1425,"z":3000,"radius":7,"amount":1,"label":"Follow Merrow into the Undervault’s wax cellars"}]},{"id":"sentries","journal":"The wax cellars are guarded by sentries poured from candle-ends. They have noticed me.","objectives":[{"type":"event","event":"death","targets":["a3c0a000-0001-4000-9000-000000000005","a3c0a000-0001-4000-9000-000000000006"],"amount":2,"label":"Break the Tallow sentries"}]},{"id":"regent","journal":"Past the sentries, in the old Varrow chapel, the wax king has woken: the Tallow Regent, wearing the Varrow crown. Merrow is singing to it.","onEnter":{"cutscene":"regent"},"objectives":[{"type":"kill","target":"a3c0a000-0001-4000-9000-000000000007","amount":1,"label":"Defeat the Tallow Regent"},{"type":"have","target":"custom_qa_varrow_crown","amount":1,"label":"Take the melted Varrow crown"}]},{"id":"judgement","journal":"The Tallow Regent is a puddle and the Varrow crown has slumped in the heat. Lady Merrow is cornered in the chapel. Her fate is in my hands.","npc":"a3c0a000-0001-4000-8000-000000000008","objectives":[{"type":"talk","target":"a3c0a000-0001-4000-8000-000000000008","amount":1,"label":"Confront Lady Merrow in the chapel","dialogue":[{"who":"npc","text":"Do you know what it is to be the last of something? Every portrait in the Keep was once my family."},{"who":"npc","text":"I did not want the throne. I wanted someone in it who remembered us."}]}],"dialogue":{"choice":[{"who":"npc","text":"Well? The Watch is coming down the stair. Decide, hero."}]},"choices":[{"id":"exile","label":"Go. Take the river road and never come back to Birchford.","flags":{"exiled_merrow":true},"dialogue":[{"who":"npc","text":"Mercy. How terribly unfashionable. ...Thank you."}]},{"id":"trial","label":"You’ll stand trial before the court you lied to.","flags":{"tried_merrow":true},"dialogue":[{"who":"npc","text":"Then I shall wear my best gown. If I must lose, I will lose beautifully."}]}]},{"id":"crown","journal":"I have decided Lady Merrow’s fate. The melted Varrow crown should go to Captain Varn at Crown Court.","objectives":[{"type":"collect","target":"custom_qa_varrow_crown","amount":1,"label":"Give the melted Varrow crown to Captain Varn"}]}],"cutscenes":{"feast":{"name":"The Feast of Lamps","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"The Feast of Lamps","subtitle":"Birchford Keep, at dusk","ms":2400},{"say":{"who":"npc","name":"Captain Isolde Varn","text":"Merrow will toast the Queen’s health in a minute. She does it beautifully. Let her finish. Then we begin."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"unmasked":{"name":"Unmasked","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"The Mistress unmasked","subtitle":"Crown Court, Birchford","ms":2400},{"say":{"who":"npc","name":"Lady Merrow Ashgrove","text":"A cipher read aloud at my own feast? How dreadfully rude. Do excuse me. I have a king to wake."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"regent":{"name":"The Tallow Regent","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000008","distance":5,"height":2.2,"angle":30}},{"title":"The Tallow Regent","subtitle":"The Undervault chapel","ms":2400},{"say":{"who":"npc","name":"Lady Merrow Ashgrove","text":"Rise, Your Majesty. The Varrow line has waited long enough."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000008","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"dawn":{"name":"Dawn over the Keep","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0001-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"The Lamplit Court","subtitle":"Birchford, the morning after","ms":2400},{"say":{"who":"npc","name":"Odo Penwhistle","text":"The Treasury stair is open to you now, and the Quartermaster sends his compliments. And a bill. For the chapel floor."},"shot":{"around":"a3c0a000-0001-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"dawn"},"journalDone":"At the Feast of Lamps, Captain Varn unmasked Lady Merrow Ashgrove. I followed her into the Undervault, broke her tallow sentries and melted the Tallow Regent, the wax king of House Varrow. Birchford is safe, the Treasury stair is open to me, and Her Majesty sent a signet that brings me back to Crown Court.","journalVariants":[{"ifFlags":{"exiled_merrow":true},"text":"I let Merrow go into exile. Some say she sings in a river inn now."},{"ifFlags":{"tried_merrow":true},"text":"Merrow stood trial before the court. She wore her best gown."}],"gold":5000,"xp":{"crafting":60000,"agility":40000,"defence":35000,"strength":30000},"items":{"custom_qa_tallow_signet":1,"armor:crownwardenSigil":1},"lamps":[{"amount":20000,"minLevel":40,"label":"Crown lamp (any skill of level 40+)"}],"unlocks":[{"type":"teleport","id":"teleport.crown-court","label":"Signet of the Lamplit Court: Crown Court, Birchford","x":-232,"z":168},{"type":"area","id":"area.crown-arcade","label":"Treasury stair: the Royal Quartermaster and the Gilded Regent (harder mode)"},{"type":"area","id":"lair:hollow_throne","label":"The Hollow Throne: the first Varrow king sleeps below Hollowmere"},{"type":"flag","id":"crown.lamplit_court","label":"Birchford honours the Lamplit Court"},{"type":"dialogue","id":"dialogue.crown-varn-5","label":"Captain Varn salutes you","npc":"a3c0a000-0001-4000-8000-000000000004","lines":[{"who":"npc","text":"Captain of the Watch, thanks to you, and not hanged, thanks to you. I count both."},{"who":"npc","text":"Merrow’s papers name one more Varrow: the first king, the Hollow one, in the crypts below Hollowmere. Go carefully if you go."}]},{"type":"dialogue","id":"dialogue.crown-odo-5","label":"Odo, Chancery hero","npc":"a3c0a000-0001-4000-8000-000000000001","lines":[{"who":"npc","text":"They promoted me to Clerk. Not under. Just Clerk. I had a cake made. It was sealed."}]},{"type":"dialogue","id":"dialogue.crown-merrow-exile","label":"Merrow’s empty chair","npc":"a3c0a000-0001-4000-8000-000000000005","ifFlags":{"exiled_merrow":true},"lines":[{"who":"npc","text":"(Lady Merrow’s chair stands empty. Someone has left a single candle on it, unlit.)"}]},{"type":"dialogue","id":"dialogue.crown-merrow-trial","label":"Merrow awaits judgement","npc":"a3c0a000-0001-4000-8000-000000000005","ifFlags":{"tried_merrow":true},"lines":[{"who":"npc","text":"My trial is on Thursday. I have chosen the gown. Do come; the court has never looked so alive."}]},{"type":"dialogue","id":"dialogue.crown-fenn-5","label":"Fenn’s commemorative candles","npc":"a3c0a000-0001-4000-8000-000000000003","lines":[{"who":"npc","text":"Feast of Lamps souvenir candles! Shaped like the Tallow Regent! Too soon? Too soon."}]}]}$q$::jsonb);

commit;
